@module util  src=util.lua  loc=638  mode=namespace  self=util

# Invariants & contracts
  @invariant  util.OPEN is the canonical "deliberately unbounded tail" marker for a note's endppqL. It is math.huge, so arithmetic on an open tail just works (inf + finite = inf, inf > finite = true) — callers no longer special-case the sentinel except to communicate intent. util.serialise/unserialise round-trip the non-finite floats via explicit inf/-inf/nan literals so the on-disk form is stable. Distinct from util.REMOVE: REMOVE clears a key on assign; OPEN is a persisted *value* of endppqL.  @ 42

# Module-level constants
  @const util = {}  @ 5
      @invariant  stateless module: pure helpers, no module-level mutable state beyond the REMOVE/OPEN sentinels  @ 3
      @invariant  util.REMOVE is the canonical delete marker honoured by assign and by mm/cm assignment APIs  @ 4
  @const BASE36 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'  @ 322
  @const BASE62 = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRST...  @ 341
  @const LUA_KEYWORDS = {}  @ 540
  @const prettyEmit  @ 565   -- forward decl (mutual recursion with emitTable)

# Private functions
  @fn print(...)  @ 15-17
  @fn escape_string(s)  @ 208-223
  -- Lua-literal disk format (human-editable; read by load(), never P_EXT)
  @fn bareKey(k)  @ 546-548
  @fn luaNumber(n)  @ 551-556
      -- inf/nan are not bare Lua, but their arithmetic forms are and need no env.
  @fn nonFiniteNote(v)  @ 559-563
      -- Inline note so a hand-editor recognises the arithmetic non-finite forms.
  @fn emitTable(tbl, indent, seen)  @ 567-603

# Public API (util.*)
  @api util.print(...)  @ 7-13
  @api util.print_r(root)  @ 19-38
  @api util.assign(t1,t2)  @ 46-57
      @contract  values equal to util.REMOVE clear the key from t1 instead of being assigned  @ 45
  @api util.add(tbl, val)  @ 59-62
  @api util.atomic(label, fn)  @ 68-77
      -- Wrap fn so each call is one REAPER undo entry. label is the undo
      -- description; the wrapper forwards args, propagates errors after
      -- closing the block, and is a no-op when reaper.Undo_BeginBlock is
      -- absent (test harness).
  @api util.picker(keys)  @ 82-97
      -- pick re-parses its key string on every call: nothing at a site that runs a few times, and
      -- 9.6ms of pure gmatch at one that runs per note of a dense channel. Hoist a picker there.
      @contract  parses `keys` once, returns a pick over it; the closure owns the list, no module state  @ 79
  @api util.pick(src, keys, adds)  @ 99-108
  @api util.bucket(buckets, key, val)  @ 110-115
  @api util.key(...)  @ 121-135
      -- Opaque compound key: join identity fields with NUL, which can't appear
      -- in a guid, track-key, or stringified scalar. Never split back apart.
      -- Small arities unroll to a single concat (per-event on the load/rebuild key
      -- paths); tostring kept per arg so output is identical for any arg type.
  @api util.keys(t)  @ 137-141
  @api util.compact(t, n)  @ 144-148
      -- Sparse → dense; n is the pre-sparse length.
  @api util.seek(items, mode, key, filter, keyFn)  @ 151-172
      @contract  assumes items sorted by keyFn (defaults to .ppq); 'before' modes scan to first miss then stop  @ 150
  @api util.insertSorted(list, item, less)  @ 176-184
      -- Splice item into an already-sorted list at its lower bound (before any element not less than it),
      -- by the same less-than a table.sort(list, less) would use. O(log n) search plus the shift.
  @api util.clone(src, exclude, deep)  @ 187-196
      @contract  exclude applies only to the outermost table; deep recursion drops the exclude set  @ 186
  @api util.deepClone(src)  @ 198
  @api util.deepEq(a, b)  @ 200-206
  @api util.installHooks(owner)  @ 226-243
      @contract  listeners filter by signal name at registration; forward requires source itself ran installHooks  @ 225
  @api util.isNote(e)  @ 245
  @api util.between(events, lo, hi, filter)  @ 248-259
      @contract  iterates events with ppq in half-open [lo, hi); adjacent windows tile without overlap  @ 247
  @api util.clamp(val,min,max)  @ 261-269
  @api util.setDigit(val, d, pos, base, keepBelow)  @ 271-276
  @api util.snapTo(v, dir, interval)  @ 279-282
      @contract  advances at least one full interval; values already on a boundary do not no-op  @ 278
  @api util.nudgedScalar(v, lo, hi, dir, interval)  @ 284-287
  @api util.oneOf(choices, txt)  @ 289-294
  @api util.round(n, to)  @ 296-302
  @api util.gcd(a, b)  @ 304-308
  @api util.lcm(a, b)  @ 310
